!function(){"use strict";function transportistaCtrl($scope,transportistaSvc,tS){$scope.json={typeList:0},$scope.resultModal=function(result){"object"==typeof result&&$scope.getAll()},$scope.getAll=function(){try{showLoader(),$scope.transportistas=[],transportistaSvc.getAll($scope.json).then(response=>{$scope.transportistas=response,hideLoader()}).catch(error=>{hideLoader(),console.log(error)})}catch(error){console.log(response),hideLoader()}},$scope.getAll(),$scope.askToDelete=async item=>{try{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro/a de eliminar este registro ahora?</small>",showConfirmButton:!0,confirmButtonText:"Sí, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&(showLoader(),transportistaSvc.delete(item.idTransportista).then(response=>{hideLoader(),"0"==response.code&&tS.toastr("warning",response.message),"1"==response.code&&(tS.toastr("success",response.message),$scope.getAll())}).catch(error=>{console.log(error),hideLoader()}))}catch(error){console.log(error)}}}app.controller("transportistaCtrl",transportistaCtrl),transportistaCtrl.$inject=["$scope","transportistaService","toastService"]}(window.angular);